import { test, expect, setThemePlan } from "../helpers/theme-browser";

for (const [name, appearance, mode] of [
  ["Lavender", "purple", "light"],
  ["Nightbloom", "purple", "dark"],
  ["Chalk", "vercel", "light"],
  ["Obsidian", "vercel", "dark"],
] as const) {
  test(`${name}: fields and actions respond without changing layout`, async ({
    page,
    themeUser,
  }, info) => {
    await setThemePlan(themeUser, "PAID");
    await page.addInitScript(
      ({ appearance, mode }) => {
        localStorage.setItem("mailloop-appearance", appearance);
        localStorage.setItem("mailloop-theme", mode);
      },
      { appearance, mode },
    );
    await page.goto("/contacts");
    await expect(page.locator("html")).toHaveAttribute(
      "data-appearance",
      appearance,
    );
    await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
    await page.evaluate(() => document.fonts.ready);
    const email = page
      .getByRole("textbox", { name: "Email", exact: true })
      .last();
    const save = page.getByRole("button", {
      name: "Save contact",
      exact: true,
    });
    await expect(email).toBeVisible();
    const initial = await email.evaluate((el) => [
      el.clientWidth,
      el.clientHeight,
    ]);
    await email.focus();
    await expect(email).toHaveCSS("caret-color", /rgb\(/);
    await expect(email).toHaveCSS("outline-style", "solid");
    await expect(email).toHaveCSS("outline-width", "2px");
    await email.fill("[REDACTED_EMAIL]");
    await page.keyboard.press("ArrowLeft");
    await expect(email).toHaveValue("[REDACTED_EMAIL]");
    expect(
      await email.evaluate((el) => [el.clientWidth, el.clientHeight]),
    ).toEqual(initial);
    await email.screenshot({
      path: info.outputPath(`${name.toLowerCase()}-field.png`),
    });

    const buttonSize = await save.evaluate((el) => [
      el.clientWidth,
      el.clientHeight,
    ]);
    await save.focus();
    await page.keyboard.down("Space");
    await expect(save).toHaveCSS(
      "scale",
      appearance === "vercel" ? "1" : "0.985",
    );
    expect(
      await save.evaluate((el) => [el.clientWidth, el.clientHeight]),
    ).toEqual(buttonSize);
    await page.keyboard.up("Space");
    await page.emulateMedia({ reducedMotion: "reduce" });
    await expect(email).toHaveCSS("transition-duration", "0s");
    await expect(save).toHaveCSS("scale", "1");
    await expect(save).toHaveCSS("transition-duration", "0s");
  });
}

test("upgrade dialog opens, closes, and respects reduced motion", async ({
  page,
  themeUser,
}) => {
  await setThemePlan(themeUser, "FREE");
  await page.goto("/contacts");
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page
    .getByRole("menuitemradio", { name: "Chalk Premium Light" })
    .click();
  const dialog = page.getByRole("dialog", { name: "Upgrade to Premium" });
  await expect(dialog).toBeVisible();
  await expect(dialog).toHaveAttribute("data-state", "open");
  await expect(dialog).toHaveCSS("animation-name", "dialog-content-in");
  await dialog.getByRole("button", { name: "Close upgrade dialog" }).click();
  await expect(dialog).toHaveCount(0);
  await page.emulateMedia({ reducedMotion: "reduce" });
  await page.getByRole("button", { name: "Choose appearance" }).click();
  await page
    .getByRole("menuitemradio", { name: "Chalk Premium Light" })
    .click();
  await expect(dialog).toBeVisible();
  await expect(dialog).toHaveCSS("animation-name", "none");
});
